# Code generated by Claude
"""
D2 follow-up: the margins of the best stage 2 survivors at each heading (data/d2/<layout>_stage2.json from experiments/stance_two_points.py), to show the cost of keeping the
staging heading (facing the bench, -90 degrees) against turning the base.

    source .venv/bin/activate
    MUJOCO_GL=egl python experiments/stance_two_points_by_heading.py [--layout current] [--per 2]

For each heading the survivors with the most surviving grid neighbours (x +-3 cm, pedestal +-1 step) are evaluated with experiments/stance_two_points.evaluate (collision-free support of
all 24 points, the joint margin, the tolerances). Writes OUT/<layout>_by_heading.json.
"""

import argparse
import json
import math
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import numpy as np  # noqa: E402

import stance_two_points as S  # noqa: E402


def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[1])
    ap.add_argument("--layout", default="current")
    ap.add_argument("--out", default=str(PROJECT_ROOT / "data" / "d2"))
    ap.add_argument("--per", type=int, default=2)
    ap.add_argument("--seeds", type=int, default=24)
    a = ap.parse_args()
    out = Path(a.out)
    s2 = np.array(json.loads((out / f"{a.layout}_stage2.json").read_text())["survivors"])
    ctx = S.Ctx(a.layout)
    key = {tuple(np.round(r, 6)) for r in s2}
    xs = sorted({round(r[0], 6) for r in s2})
    x_step = 0.03
    qs = sorted({round(r[3], 6) for r in s2})
    q_step = 0.418 / 7
    def proxy(r):
        return sum(tuple(np.round((r[0] + dx, r[1], r[2], r[3] + dq * q_step), 6)) in key for dx, dq in ((x_step, 0), (-x_step, 0), (0, 1), (0, -1)))
    rows = []
    for th in sorted({round(math.degrees(r[2])) for r in s2}, reverse=True):
        grp = [r for r in s2 if round(math.degrees(r[2])) == th]
        best = sorted(grp, key=lambda r: (-proxy(r), r[3], abs(r[0] - 0.75)))[:a.per]
        S.log(f"heading {th}: {len(grp)} survivors, evaluating {len(best)}")
        for r in best:
            e = S.evaluate(ctx, r, a.seeds)
            rows.append(e)
            S.log("  " + S.describe(e))
    S.save(out / f"{a.layout}_by_heading.json", rows)


if __name__ == "__main__":
    main()
